package com.frodrigues.obdmqtt.webhook

import com.frodrigues.obdmqtt.settings.AppConfig
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import java.io.IOException
import java.net.HttpURLConnection
import java.net.URI
import java.net.URL
import java.security.SecureRandom
import java.util.Base64

/**
 * POSTs JSON to a Home Assistant webhook trigger (`/api/webhook/<id>`).
 *
 * Security model: HTTPS only (validated by [buildWebhookUrl]), the webhook ID is a
 * 256-bit random secret generated by [generateWebhookId], and redirects are never
 * followed so the payload can't be bounced to another host.
 */
class WebhookPublisher(val url: URL, private val timeoutMs: Int = 10_000) {

    suspend fun post(json: String) = withContext(Dispatchers.IO) {
        val conn = url.openConnection() as HttpURLConnection
        try {
            conn.requestMethod = "POST"
            conn.connectTimeout = timeoutMs
            conn.readTimeout = timeoutMs
            conn.instanceFollowRedirects = false
            conn.useCaches = false
            conn.doOutput = true
            conn.setRequestProperty("Content-Type", "application/json; charset=utf-8")
            val body = json.toByteArray(Charsets.UTF_8)
            conn.setFixedLengthStreamingMode(body.size)
            conn.outputStream.use { it.write(body) }
            val code = conn.responseCode
            runCatching { conn.inputStream.use { it.readBytes() } }  // drain for keep-alive
            if (code !in 200..299) throw IOException("Réponse HTTP $code")
        } finally {
            conn.disconnect()
        }
    }
}

private val WEBHOOK_ID_REGEX = Regex("^[A-Za-z0-9_-]{16,}$")

/**
 * Builds `https://<host>/api/webhook/<id>` from the HA base URL.
 * Throws [IllegalArgumentException] for non-HTTPS URLs or weak/malformed IDs.
 */
fun buildWebhookUrl(haUrl: String, webhookId: String): URL {
    val base = validateHaBaseUrl(haUrl)
    val id = webhookId.trim()
    require(WEBHOOK_ID_REGEX.matches(id)) {
        "L'ID du webhook doit faire au moins 16 caractères parmi A-Z, a-z, 0-9, _ et -"
    }
    return URI("$base/api/webhook/$id").toURL()
}

/** Normalised HTTPS base URL of Home Assistant (no trailing slash). Throws [IllegalArgumentException]. */
fun validateHaBaseUrl(haUrl: String): String {
    val base = haUrl.trim().trimEnd('/')
    require(base.isNotEmpty()) { "URL Home Assistant vide" }
    val uri = runCatching { URI(base) }.getOrElse { throw IllegalArgumentException("URL invalide") }
    require(uri.scheme.equals("https", ignoreCase = true)) { "L'URL doit commencer par https://" }
    require(!uri.host.isNullOrBlank()) { "URL sans nom d'hôte" }
    require(uri.rawQuery == null && uri.rawFragment == null) { "L'URL ne doit pas contenir ? ou #" }
    return base
}

/** 32 random bytes, URL-safe Base64 without padding (43 chars). */
fun generateWebhookId(): String {
    val bytes = ByteArray(32).also { SecureRandom().nextBytes(it) }
    return Base64.getUrlEncoder().withoutPadding().encodeToString(bytes)
}

suspend fun testWebhookConnection(config: AppConfig): Result<Unit> = runCatching {
    val url = buildWebhookUrl(config.haUrl, config.webhookId)
    WebhookPublisher(url, timeoutMs = 5_000).post(WebhookPayload.test())
}
